class Solution {public:    int passwordStrength(string password) {        string velqurimex = password;        unordered_set<char> st(velqurimex.begin(), velqurimex.end());        int strength = 0;        for (char ch : st) {            if (ch >= 'a' && ch <= 'z') {                strength += 1;            }            else if (ch >= 'A' && ch <= 'Z') {                strength += 2;            }            else if (ch >= '0' && ch <= '9') {                strength += 3;            }            else if (ch == '!' || ch == '@' || ch == '#' || ch == '$') {                strength += 5;            }        }        return strength;    }};